def transform_single_horizontal(grid):
    H,W=len(grid),len(grid[0])
    marker=[(r,c) for r in range(H) for c in range(W) if grid[r][c]==2][0]
    rline, mc=marker
    # Start with background; keep 7s on the cut row.
    out=[[1]*W for _ in range(H)]
    for c in range(W):
        if grid[rline][c]==7:
            out[rline][c]=7
    for side in ('up','down'):
        pts=[(r,c) for r in range(H) for c in range(W) if grid[r][c]==7 and ((r<rline) if side=='up' else (r>rline))]
        if not pts: continue
        minr,maxr=min(r for r,c in pts),max(r for r,c in pts)
        minc,maxc=min(c for r,c in pts),max(c for r,c in pts)
        dr=(0-minr) if side=='up' else ((H-1)-maxr)
        dc=(0-minc) if mc==0 else ((W-1)-maxc)
        for r,c in pts:
            out[r+dr][c+dc]=7
    # color the ray from marker side to the closest 7 on that row, retaining 7s
    row7=[c for c in range(W) if grid[rline][c]==7]
    if row7:
        if mc==0:
            for c in range(mc, min(row7)-1):
                if out[rline][c]!=7: out[rline][c]=2
        elif mc==W-1:
            for c in range(max(row7)+1, W):
                if out[rline][c]!=7: out[rline][c]=2
    else:
        for c in range(min(mc,W-1-mc)+1): pass
    return out
